"""Textos propios de la edición de carne, en los mismos siete idiomas.

Lo que ya dice la plataforma de cocina se reutiliza tal cual (`meat.*`,
`trace.*`, `inv.*`, `waste.*`, `common.*`…). Aquí solo están las pantallas que
la edición de carne tiene y la otra no: recepción de primales, despiece,
descongelado, el catálogo de cortes y la carta de carnes.

`install()` los vuelca en el catálogo general, así que en las plantillas se
piden igual que los demás: `t("m.tg.title")`. Un test comprueba que ningún
idioma se deje claves sin traducir.
"""
