CATALOGUES = {"es": ES, "en": EN, "fr": FR, "de": DE, "nl": NL, "ar": AR, "hu": HU}


def install() -> None:
    """Añade los textos de carne al catálogo general. Idempotente."""
    for code, table in CATALOGUES.items():
        i18n.TRANSLATIONS.setdefault(code, {}).update(table)


install()
